#!/usr/bin/env node
// Builds js/app.bundle.js (the classic, file://-compatible runtime that index.html loads)
// from the readable sources: js/icons.js + js/app.js + js/entry-ui.js.
//
//   node tools/build-bundle.js            write js/app.bundle.js
//   node tools/build-bundle.js --check    exit 1 if js/app.bundle.js is out of date
//
// No dependencies. ES module syntax is stripped because the bundle must stay a classic script.
'use strict';
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const read = f => fs.readFileSync(path.join(root, f), 'utf8').replace(/\r\n/g, '\n');

function version() {
  const m = read('sw.js').match(/moze-v([\d.]+)-shell/);
  if (!m) throw new Error('cannot read version from sw.js CACHE name');
  return m[1];
}

function build() {
  const icons = read('js/icons.js').replace(/^export\s+/gm, '');
  const app = read('js/app.js');
  const analysis = read('js/analysis.js');
  const budgets = read('js/budgets.js');
  const categories = read('js/categories.js');
  const search = read('js/search.js');
  const projects = read('js/projects.js');
  const entry = read('js/entry-ui.js').replace(/^\s*import\s+[^;]+;\s*$/gm, '');
  const out = [
    `/* 帳小簿 V${version()} low-memory bundle — file:// compatible runtime */`,
    `/* GENERATED by tools/build-bundle.js from js/icons.js + js/app.js + js/analysis.js + js/budgets.js + js/categories.js + js/search.js + js/projects.js + js/entry-ui.js — do not edit by hand. */`,
    icons.trimEnd(),
    '',
    app.trimEnd(),
    '',
    analysis.trimEnd(),
    '',
    budgets.trimEnd(),
    '',
    categories.trimEnd(),
    '',
    search.trimEnd(),
    '',
    projects.trimEnd(),
    '',
    entry.trim(),
    '',
  ].join('\n');
  if (/^\s*(import|export)\s/m.test(out)) throw new Error('bundle still contains import/export');
  return out;
}

const target = path.join(root, 'js', 'app.bundle.js');
const next = build();
if (process.argv.includes('--check')) {
  const cur = fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n');
  if (cur !== next) { console.error('js/app.bundle.js is OUT OF DATE — run: node tools/build-bundle.js'); process.exit(1); }
  console.log('js/app.bundle.js is up to date');
} else {
  fs.writeFileSync(target, next);
  console.log(`wrote js/app.bundle.js (${next.length} chars)`);
}
